<?php require_once __DIR__.'/includes/functions.php';require_login();$title='Dashboard';$counts=[];foreach(['books'=>'Books','users'=>'Accounts','transactions'=>'Transactions','activity_logs'=>'Activity events'] as $t=>$label){if($t==='users'&&current_user()['role']!=='admin')continue;$r=$db->query("SELECT COUNT(*) n FROM `$t`")->fetch_assoc();$counts[$label]=$r['n'];}$pending=$db->query("SELECT COUNT(*) n FROM transactions WHERE status='pending'")->fetch_assoc()['n'];$available=$db->query('SELECT COALESCE(SUM(available_copies),0) n FROM books')->fetch_assoc()['n'];$overdue=$db->query("SELECT COUNT(*) n FROM transactions WHERE status='released' AND due_date<CURDATE()")->fetch_assoc()['n'];require 'includes/header.php';?><h1>Dashboard</h1><p class="muted">Welcome, <?=e(current_user()['name'])?>. Your role is <b><?=e(current_user()['role'])?></b>.</p><div class="grid"><?php foreach($counts as $k=>$v):?><div class="card"><div class="muted"><?=e($k)?></div><div class="stat"><?=e($v)?></div></div><?php endforeach;?><div class="card"><div class="muted">Pending requests</div><div class="stat"><?=e($pending)?></div></div><div class="card"><div class="muted">Available copies</div><div class="stat"><?=e($available)?></div></div><div class="card"><div class="muted">Overdue loans</div><div class="stat"><?=e($overdue)?></div></div></div><div class="panel"><h2>Quick actions</h2><p><a class="btn" href="<?=url('books.php')?>">Browse books</a> <a class="btn secondary" href="<?=url('transactions.php')?>">Manage transactions</a> <a class="btn secondary" href="<?=url('reports.php')?>">Reports</a><?php if(current_user()['role']==='admin'):?> <a class="btn secondary" href="<?=url('users.php')?>">Manage users</a><?php endif;?></p><p>Workflow: users submit borrow/reservation requests → staff/admin approve or reject → approved borrow requests are released → returned copies are added back to inventory.</p></div><?php if(in_array(current_user()['role'],['admin','staff'])):?><div class="panel"><h2>Request processing queue</h2><p>Pending requests are processed in first-in, first-out order. The queue implementation is available in <a href="<?=url('queue_demo.php')?>">Data Structure Demonstration</a>.</p></div><?php endif;?><?php require 'includes/footer.php';?>
